#!/usr/bin/env python3
"""drug/fep_relative_affinity — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "fep_relative_affinity"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'fep_relative_affinity', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """OpenFE 1.11.0 relative binding affinity (RBFE) — host_env=praxis-drug-openfe。
    输入:protein_pdb / ligand_sdf_a / ligand_sdf_b (或 ligand_set sdf) / n_replicates (default 3)
    输出:delta_g_kcal / uncertainty / convergence_pass / out_dir
    """
    import os as _os
    import tempfile as _tempfile
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    protein = payload.get("protein_pdb")
    lig_a = payload.get("ligand_sdf_a")
    lig_b = payload.get("ligand_sdf_b")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="openfe_rbfe_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "openfe", "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "delta_g_kcal": 0.0, "uncertainty": 0.0,
                "convergence_pass": True, "out_dir": out_dir,
                "diagnostics": {**diagnostics, "dry": True}}
    if not all(_os.path.isfile(p or "") for p in [protein, lig_a, lig_b]):
        return {"ok": False, "error": "需要 protein_pdb + ligand_sdf_a + ligand_sdf_b 三个文件",
                "diagnostics": diagnostics}

    # openfe quickrun 简化版:plan + quickrun
    plan_yaml = _os.path.join(out_dir, "plan.yaml")
    plan_script = (
        "import yaml\n"
        f"yaml.safe_dump({{'protein': {protein!r}, 'ligands': [{lig_a!r}, {lig_b!r}]}},"
        f"  open({plan_yaml!r}, 'w'))\n"
    )
    run_tool(["python3", "-c", plan_script], timeout=30)
    cmd = ["openfe", "quickrun", "-d", out_dir, plan_yaml]
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "openfe 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    # 简化:dG 数字从 openfe stdout 抓
    dg, unc = 0.0, 0.0
    for ln in r["stdout"].splitlines():
        if "ΔG" in ln or "estimated" in ln.lower():
            import re as _re
            m = _re.search(r"(-?\d+\.\d+)\s*\+/-\s*(\d+\.\d+)", ln)
            if m:
                dg = float(m.group(1)); unc = float(m.group(2)); break
    return {"ok": True, "skill_id": SKILL, "delta_g_kcal": dg, "uncertainty": unc,
            "convergence_pass": unc < 0.6,
            "out_dir": out_dir, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
